let ink = CGColor(red: 0.07, green: 0.12, blue: 0.16, alpha: 1)
let muted = CGColor(red: 0.27, green: 0.31, blue: 0.33, alpha: 1)
let paper = CGColor(red: 0.99, green: 0.975, blue: 0.945, alpha: 1)
let orange = CGColor(red: 1.00, green: 0.64, blue: 0.40, alpha: 1)
