struct Canvas {
    let context: CGContext

    func rect(_ x: CGFloat, _ y: CGFloat, _ width: CGFloat, _ height: CGFloat, _ color: CGColor) {
        context.setFillColor(color)
        context.fill(CGRect(x: x, y: y, width: width, height: height))
    }

    func stroke(_ x1: CGFloat, _ y1: CGFloat, _ x2: CGFloat, _ y2: CGFloat,
                _ color: CGColor = lineColor, _ width: CGFloat = 0.65) {
        context.setStrokeColor(color)
        context.setLineWidth(width)
        context.beginPath()
        context.move(to: CGPoint(x: x1, y: y1))
        context.addLine(to: CGPoint(x: x2, y: y2))
        context.strokePath()
    }

    func text(_ value: String, _ x: CGFloat, _ y: CGFloat, _ size: CGFloat,
              _ face: String = \"HelveticaNeue\", color: CGColor = ink,
              tracking: CGFloat = 0, right: Bool = false, maxWidth: CGFloat) {
        let font = CTFontCreateWithName(face as CFString, size, nil)
        let attrs = [
            kCTFontAttributeName: font,
            kCTForegroundColorAttributeName: color,
            kCTKernAttributeName: tracking as NSNumber
        ] as CFDictionary
        let string = CFAttributedStringCreate(nil, value as CFString, attrs)"'!
        let line = CTLineCreateWithAttributedString(string)
        let width = CGFloat(CTLineGetTypographicBounds(line, nil, nil, nil))
        precondition(width <= maxWidth, "Text exceeds available width: '"\\(value) (\\(width) > \\(maxWidth))\")
        context.saveGState()
        context.translateBy(x: right ? x - width : x, y: y + CTFontGetAscent(font))
        context.scaleBy(x: 1, y: -1)
        context.textMatrix = .identity
        context.textPosition = .zero
        CTLineDraw(line, context)
        context.restoreGState()
    }

    func gear(_ x: CGFloat, _ y: CGFloat, _ radius: CGFloat) {
        let outline = CGMutablePath()
        let teeth = 16
        let toothPitch = 2 * CGFloat.pi / CGFloat(teeth)
        let profile: [(CGFloat, CGFloat)] = [(0, 0.89), (0.22, 0.89), (0.34, 1),
                                             (0.65, 1), (0.77, 0.89)]
        for tooth in 0..<teeth {
            for (index, point) in profile.enumerated() {
                let (offset, proportion) = point
                let angle = (CGFloat(tooth) + offset) * toothPitch
                let vertex = CGPoint(x: x + cos(angle) * radius * proportion,
                                     y: y + sin(angle) * radius * proportion)
                if tooth == 0 && index == 0 {
                    outline.move(to: vertex)
                } else {
                    outline.addLine(to: vertex)
                }
            }
        }
        outline.closeSubpath()
        context.setFillColor(orange)
        context.setStrokeColor(ink)
        context.setLineWidth(max(0.75, radius * 0.035))
        context.setLineJoin(.round)
        context.addPath(outline)
        context.drawPath(using: .fillStroke)

        func circle(at center: CGPoint, radius: CGFloat, fill: CGColor? = nil) {
            let box = CGRect(x: center.x - radius, y: center.y - radius,
                             width: radius * 2, height: radius * 2)
            if let fill {
                context.setFillColor(fill)
                context.fillEllipse(in: box)
            }
            context.strokeEllipse(in: box)
        }

        circle(at: CGPoint(x: x, y: y), radius: radius * 0.74)
        for hole in 0..<5 {
            let angle = CGFloat(hole) * 2 * .pi / 5 - .pi / 2
            let point = CGPoint(x: x + cos(angle) * radius * 0.51,
                                y: y + sin(angle) * radius * 0.51)
            circle(at: point, radius: radius * 0.105, fill: paper)
        }
        circle(at: CGPoint(x: x, y: y), radius: radius * 0.23, fill: paper)
    }
}

