func place(_ c: Canvas, x: CGFloat, y: CGFloat, width: CGFloat, height: CGFloat,
           draw: (Canvas) -> Void) {
    let right = x + width
    let bottom = y + height
    for edge in [x, right] {
        c.stroke(edge, y - 9, edge, y - 2, cropColor, 0.5)
        c.stroke(edge, bottom + 2, edge, bottom + 9, cropColor, 0.5)
    }
    for edge in [y, bottom] {
        c.stroke(x - 9, edge, x - 2, edge, cropColor, 0.5)
        c.stroke(right + 2, edge, right + 9, edge, cropColor, 0.5)
    }
    c.context.saveGState()
    c.context.translateBy(x: x, y: y)
    draw(c)
    c.context.restoreGState()
}

func write(_ filename: String, title: String, draw: (Canvas) -> Void) {
    let url = URL(fileURLWithPath: filename)
    var bounds = CGRect(origin: .zero, size: page)
    let info = [kCGPDFContextTitle: title] as CFDictionary
    let context = CGContext(url as CFURL, mediaBox: &bounds, info)!
    context.beginPDFPage(nil)
    context.translateBy(x: 0, y: page.height)
    context.scaleBy(x: 1, y: -1)
    draw(Canvas(context: context))
    context.endPDFPage()
    context.closePDF()
}

